CREATE TABLE admin_orders(id BIGINT PRIMARY KEY AUTO_INCREMENT,number VARCHAR(255) NOT NULL UNIQUE,user_id BIGINT NOT NULL,currency VARCHAR(255) NOT NULL DEFAULT 'CNY',total BIGINT NOT NULL CHECK(total>=0),status VARCHAR(255) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','completed','cancelled')),request_key VARCHAR(255) NOT NULL UNIQUE,created BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP()),FOREIGN KEY (user_id) REFERENCES loom_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE admin_order_items(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,name VARCHAR(255) NOT NULL,quantity BIGINT NOT NULL CHECK(quantity>0),unit_price BIGINT NOT NULL CHECK(unit_price>=0),FOREIGN KEY (order_id) REFERENCES admin_orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE admin_order_events(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,status VARCHAR(255) NOT NULL,created BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP()),FOREIGN KEY (order_id) REFERENCES admin_orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE INDEX admin_orders_user ON admin_orders(user_id,status,id);
CREATE TABLE admin_notifications(id BIGINT PRIMARY KEY AUTO_INCREMENT,event_key VARCHAR(255) NOT NULL,user_id BIGINT NOT NULL,title VARCHAR(255) NOT NULL,body LONGTEXT NOT NULL,read_at BIGINT,created BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP()),UNIQUE(event_key,user_id),FOREIGN KEY (user_id) REFERENCES loom_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE INDEX admin_notifications_user ON admin_notifications(user_id,id);
CREATE TABLE admin_channels(channel VARCHAR(255) PRIMARY KEY,enabled BIGINT NOT NULL DEFAULT 0,url VARCHAR(255) NOT NULL DEFAULT '',secret_env VARCHAR(255) NOT NULL DEFAULT '') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
INSERT INTO admin_channels(channel,enabled) VALUES('mail',0),('webhook',0);
CREATE TABLE admin_deliveries(id BIGINT PRIMARY KEY AUTO_INCREMENT,notification_id BIGINT NOT NULL,channel VARCHAR(255) NOT NULL,state VARCHAR(255) NOT NULL DEFAULT 'pending',attempts BIGINT NOT NULL DEFAULT 0,available BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP()),lease VARCHAR(255),lease_until BIGINT,error LONGTEXT,created BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP()),UNIQUE(notification_id,channel),FOREIGN KEY (notification_id) REFERENCES admin_notifications(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE INDEX admin_deliveries_ready ON admin_deliveries(state,available);
CREATE TABLE admin_failure_events(job_id BIGINT PRIMARY KEY,created BIGINT NOT NULL DEFAULT (UNIX_TIMESTAMP())) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE admin_operations_menus(menu_id BIGINT PRIMARY KEY,path VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
